{"command":"cat > /workspace/main.go << 'GO'
package main

import (
 "fmt"
 "os"
 "strings"
 "strconv"
 "image"
 "image/color"
 "image/jpeg"
 "image/png"
 "image/gif"
 "bytes"
 "net/http"
 "io"
 "path/filepath"
 "math"
 "github.com/spf13/pflag"
)

const versionStr = "v1.13.1"
const helpText = `This tool converts images into ascii art and prints them on the terminal.
Further configuration can be managed with flags.

Usage:
  ascii-image-converter [image paths/urls or piped stdin] [flags]

Flags:
  -C, --color             Display ascii art with original colors
                          If 24-bit colors aren't supported, uses 8-bit
                          (Inverts with --negative flag)
                          (Overrides --grayscale and --font-color flags)

      --color-bg          If some color flag is passed, use that color
                          on character background instead of foreground
                          (Inverts with --negative flag)
                          (Only applicable for terminal display)

  -d, --dimensions ints   Set width and height for ascii art in CHARACTER length
                          e.g. -d 60,30 (defaults to terminal height)
                          (Overrides --width and --height flags)

  -W, --width int         Set width for ascii art in CHARACTER length
                          Height is kept to aspect ratio
                          e.g. -W 60

  -H, --height int        Set height for ascii art in CHARACTER length
                          Width is kept to aspect ratio
                          e.g. -H 60

  -m, --map string        Give custom ascii characters to map against
                          Ordered from darkest to lightest
                          e.g. -m " .-+#@" (Quotation marks excluded from map)
                          (Overrides --complex flag)

  -b, --braille           Use braille characters instead of ascii
                          Terminal must support braille patterns properly
                          (Overrides --complex and --map flags)

      --threshold int     Threshold for braille art
                          Value between 0-255 is accepted
                          e.g. --threshold 170
                          (Defaults to 128)

      --dither            Apply dithering on image for braille
                          art conversion
                          (Only applicable with --braille flag)
                          (Negates --threshold flag)

  -g, --grayscale         Display grayscale ascii art
                          (Inverts with --negative flag)
                          (Overrides --font-color flag)

  -c, --complex           Display ascii characters in a larger range
                          May result in higher quality

  -f, --full              Use largest dimensions for ascii art
                          that fill the terminal width
                          (Overrides --dimensions, --width and --height flags)

  -n, --negative          Display ascii art in negative colors

  -x, --flipX             Flip ascii art horizontally

  -y, --flipY             Flip ascii art vertically

  -s, --save-img string   Save ascii art as a .png file
                          Format: <image-name>-ascii-art.png
                          Image will be saved in passed path
                          (pass . for current directory)

      --save-txt string   Save ascii art as a .txt file
                          Format: <image-name>-ascii-art.txt
                          File will be saved in passed path
                          (pass . for current directory)

      --save-gif string   If input is a gif, save it as a .gif file
                          Format: <gif-name>-ascii-art.gif
                          Gif will be saved in passed path
                          (pass . for current directory)

      --save-bg ints      Set background color for --save-img
                          and --save-gif flags
                          Pass an RGBA value
                          e.g. --save-bg 255,255,255,100
                          (Defaults to 0,0,0,100)

      --font string       Set font for --save-img and --save-gif flags
                          Pass file path to font .ttf file
                          e.g. --font ./RobotoMono-Regular.ttf
                          (Defaults to Hack-Regular for ascii and
                           DejaVuSans-Oblique for braille)

      --font-color ints   Set font color for terminal as well as
                          --save-img and --save-gif flags
                          Pass an RGB value
                          e.g. --font-color 0,0,0
                          (Defaults to 255,255,255)

      --only-save         Don't print ascii art on terminal
                          if some saving flag is passed

      --formats           Display supported input formats

  -h, --help              Help for ascii-image-converter

  -v, --version           Version for ascii-image-converter

Copyright © 2021 Zoraiz Hassan <hzoraiz8@gmail.com>
Distributed under the Apache License Version 2.0 (Apache-2.0)
For further details, visit https://github.com/TheZoraiz/ascii-image-converter
`

const formatsText = "Supported input formats:\n\nJPEG/JPG\nPNG\nWEBP\nBMP\nTIFF/TIF\nGIF\n\n"
const defaultMap = " .:-=+*#%@"
const complexMap = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"

var (
 colorFlag bool
 colorBgFlag bool
 dimensionsStr string
 widthFlag int
 heightFlag int
 mapFlag string
 brailleFlag bool
 thresholdFlag int
 ditherFlag bool
 grayscaleFlag bool
 complexFlag bool
 fullFlag bool
 negativeFlag bool
 flipXFlag bool
 flipYFlag bool
 saveImgPath string
 saveTxtPath string
 saveGifPath string
 saveBgStr string
 fontPath string
 fontColorStr string
 onlySaveFlag bool
 formatsFlag bool
 helpFlag bool
 versionFlag bool
)

func main() {
 flagSet := pflag.NewFlagSet("ascii-image-converter", pflag.ContinueOnError)
 flagSet.SetInterspersed(true)
 // Define flags
 flagSet.BoolVarP(&colorFlag, "color", "C", false, "")
 flagSet.BoolVar(&colorBgFlag, "color-bg", false, "")
 flagSet.StringVarP(&dimensionsStr, "dimensions", "d", "", "")
 flagSet.IntVarP(&widthFlag, "width", "W", 0, "")
 flagSet.IntVarP(&heightFlag, "height", "H", 0, "")
 flagSet.StringVarP(&mapFlag, "map", "m", "", "")
 flagSet.BoolVarP(&brailleFlag, "braille", "b", false, "")
 flagSet.IntVar(&thresholdFlag, "threshold", 128, "")
 flagSet.BoolVar(&ditherFlag, "dither", false, "")
 flagSet.BoolVarP(&grayscaleFlag, "grayscale", "g", false, "")
 flagSet.BoolVarP(&complexFlag, "complex", "c", false, "")
 flagSet.BoolVarP(&fullFlag, "full", "f", false, "")
 flagSet.BoolVarP(&negativeFlag, "negative", "n", false, "")
 flagSet.BoolVarP(&flipXFlag, "flipX", "x", false, "")
 flagSet.BoolVarP(&flipYFlag, "flipY", "y", false, "")
 flagSet.StringVarP(&saveImgPath, "save-img", "s", "", "")
 flagSet.StringVar(&saveTxtPath, "save-txt", "", "")
 flagSet.StringVar(&saveGifPath, "save-gif", "", "")
 flagSet.StringVar(&saveBgStr, "save-bg", "0,0,0,100", "")
 flagSet.StringVar(&fontPath, "font", "", "")
 flagSet.StringVar(&fontColorStr, "font-color", "255,255,255", "")
 flagSet.BoolVar(&onlySaveFlag, "only-save", false, "")
 flagSet.BoolVar(&formatsFlag, "formats", false, "")
 flagSet.BoolVarP(&helpFlag, "help", "h", false, "")
 flagSet.BoolVarP(&versionFlag, "version", "v", false, "")

 flagSet.Usage = func() {
  fmt.Fprint(os.Stdout, helpText)
 }

 // Need to handle parsing errors manually to match original output
 // Use custom error handling
 flagSet.ParseErrorsWhitelist.UnknownHelpFlag = true
 err := flagSet.Parse(os.Args[1:])
 if err != nil {
  errStr := err.Error()
  // pflag errors for invalid argument contain "invalid argument"
  if strings.Contains(errStr, "invalid argument") {
   fmt.Fprintln(os.Stderr, errStr)
  }
  fmt.Fprintf(os.Stderr, "Error: %v\n", errStr)
  fmt.Fprintln(os.Stderr, "")
  // Print usage as per original: It prints Usage and Flags
  // For simplicity, print helpText to stderr as well? Original prints help on error for invalid argument
  // It prints full help to stderr
  fmt.Fprint(os.Stderr, helpText)
  os.Exit(1)
 }

 // Check help/version/formats early
 if helpFlag {
  fmt.Fprint(os.Stdout, helpText)
  os.Exit(0)
 }
 if versionFlag {
  fmt.Fprintln(os.Stdout, versionStr)
  os.Exit(0)
 }
 if formatsFlag {
  fmt.Fprint(os.Stdout, formatsText)
  os.Exit(0)
 }

 // Validate flags
 if onlySaveFlag && saveImgPath == "" && saveTxtPath == "" && saveGifPath == "" {
  fmt.Fprintln(os.Stderr, "Error: you need to supply one of --save-img, --save-txt or --save-gif for using --only-save")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }
 if thresholdFlag <0 || thresholdFlag >255 {
  fmt.Fprintln(os.Stderr, "Error: threshold must be between 0 and 255")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }
 if ditherFlag && !brailleFlag {
  fmt.Fprintln(os.Stderr, "Error: image dithering is only reserved for --braille flag")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }
 // dimensions validation
 if dimensionsStr != "" {
  parts := strings.Split(dimensionsStr, ",")
  if len(parts) != 2 {
   fmt.Fprintln(os.Stderr, "Error: requires 2 dimensions, got 1")
   fmt.Fprintln(os.Stderr, "")
   os.Exit(0)
  }
  wStr := strings.TrimSpace(parts[0])
  hStr := strings.TrimSpace(parts[1])
  w, err1 := strconv.Atoi(wStr)
  h, err2 := strconv.Atoi(hStr)
  if err1 != nil || err2 != nil {
   // This should have been caught by pflag? But dimensions is string, so manual parse
   // Original prints invalid argument error via pflag for dimensions with abc
   // That's already handled by pflag? Actually dimensions flag is string, so not.
   // But for invalid like "abc,5", pflag won't error, we need to print invalid argument style?
   // Original for -d abc,5 prints: invalid argument "abc,5" for "-d, --dimensions" flag: ...
   // We should mimic that
   fmt.Fprintf(os.Stderr, "invalid argument \"%s\" for \"-d, --dimensions\" flag: strconv.Atoi: parsing \"%s\": invalid syntax\n", dimensionsStr, wStr)
   fmt.Fprintf(os.Stderr, "Error: invalid argument \"%s\" for \"-d, --dimensions\" flag: strconv.Atoi: parsing \"%s\": invalid syntax\n", dimensionsStr, wStr)
   fmt.Fprintln(os.Stderr, "")
   fmt.Fprint(os.Stderr, helpText)
   os.Exit(1)
  }
  if w <=0 || h <=0 {
   fmt.Fprintln(os.Stderr, "Error: invalid values for dimensions")
   fmt.Fprintln(os.Stderr, "")
   os.Exit(0)
  }
 }
 if widthFlag <0 {
  fmt.Fprintln(os.Stderr, "Error: invalid value for width")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }
 if widthFlag ==0 && flagSet.Changed("width") {
  // width 0 is invalid? The original for -W 0 gave? Let's test: we didn't test 0, but -W 0 should be invalid?
  // For -d 0,0 it gave invalid values for dimensions, for -W 0 maybe same invalid?
  // Let's treat 0 as invalid
  fmt.Fprintln(os.Stderr, "Error: invalid value for width")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }
 if heightFlag <0 {
  fmt.Fprintln(os.Stderr, "Error: invalid value for height")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }
 if heightFlag ==0 && flagSet.Changed("height") {
  fmt.Fprintln(os.Stderr, "Error: invalid value for height")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }
 if widthFlag !=0 && heightFlag !=0 {
  fmt.Fprintln(os.Stderr, "Error: both --width and --height can't be set. Use --dimensions instead")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }
 if mapFlag != "" && len([]rune(mapFlag)) <2 {
  fmt.Fprintln(os.Stderr, "Need at least 2 characters for --map flag")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }
 // font-color validation
 fontColorChanged := flagSet.Changed("font-color")
 if fontColorChanged {
  parts := strings.Split(fontColorStr, ",")
  if len(parts) !=3 {
   fmt.Fprintf(os.Stderr, "Error: --font-color requires 3 values for RGB, got %d\n", len(parts))
   fmt.Fprintln(os.Stderr, "")
   os.Exit(0)
  }
  for _, p := range parts {
   v, err := strconv.Atoi(strings.TrimSpace(p))
   if err != nil {
    fmt.Fprintf(os.Stderr, "invalid argument \"%s\" for \"--font-color\" flag: strconv.Atoi: parsing \"%s\": invalid syntax\n", fontColorStr, p)
    fmt.Fprintf(os.Stderr, "Error: invalid argument \"%s\" for \"--font-color\" flag: strconv.Atoi: parsing \"%s\": invalid syntax\n", fontColorStr, p)
    fmt.Fprintln(os.Stderr, "")
    fmt.Fprint(os.Stderr, helpText)
    os.Exit(1)
   }
   if v <0 || v >255 {
    fmt.Fprintln(os.Stderr, "Error: RBG values must be between 0 and 255")
    fmt.Fprintln(os.Stderr, "")
    os.Exit(0)
   }
  }
 }
 // save-bg validation
 saveBgChanged := flagSet.Changed("save-bg")
 if saveBgChanged {
  parts := strings.Split(saveBgStr, ",")
  if len(parts) !=4 {
   fmt.Fprintf(os.Stderr, "Error: --save-bg requires 4 values for RGBA, got %d\n", len(parts))
   fmt.Fprintln(os.Stderr, "")
   os.Exit(0)
  }
  for i, p := range parts {
   v, err := strconv.Atoi(strings.TrimSpace(p))
   if err != nil {
    fmt.Fprintf(os.Stderr, "invalid argument \"%s\" for \"--save-bg\" flag: strconv.Atoi: parsing \"%s\": invalid syntax\n", saveBgStr, p)
    fmt.Fprintf(os.Stderr, "Error: invalid argument \"%s\" for \"--save-bg\" flag: strconv.Atoi: parsing \"%s\": invalid syntax\n", saveBgStr, p)
    fmt.Fprintln(os.Stderr, "")
    fmt.Fprint(os.Stderr, helpText)
    os.Exit(1)
   }
   if i <3 {
    if v <0 || v >255 {
     fmt.Fprintln(os.Stderr, "Error: RBG values must be between 0 and 255")
     fmt.Fprintln(os.Stderr, "")
     os.Exit(0)
    }
   } else {
    if v <0 || v >100 {
     fmt.Fprintln(os.Stderr, "Error: Opacity value must be between 0 and 100")
     fmt.Fprintln(os.Stderr, "")
     os.Exit(0)
    }
   }
  }
 }
 // Check font file exists if provided
 if fontPath != "" {
  if _, err := os.Stat(fontPath); err != nil {
   fmt.Fprintf(os.Stderr, "Error: unable to open font file: open %s: no such file or directory\n", fontPath)
   fmt.Fprintln(os.Stderr, "")
   os.Exit(0)
  }
 }
 // Check save paths exist if provided? For save-img etc, need to check directory exists
 // We handle per image later

 args := flagSet.Args()
 // Check piped stdin
 isPiped := isStdinPiped()
 if len(args)==0 && !isPiped {
  fmt.Fprintln(os.Stderr, "Error: Need at least 1 input path/url or piped input")
  fmt.Fprintln(os.Stderr, "Use the -h flag for more info")
  fmt.Fprintln(os.Stderr, "")
  os.Exit(0)
 }

 // If piped, read stdin as one input
 var inputs []string
 var stdinData []byte
 var stdinIsImage bool
 if isPiped && len(args)==0 {
  data, err := io.ReadAll(os.Stdin)
  if err != nil || len(data)==0 {
   fmt.Fprintln(os.Stderr, "Error: Need at least 1 input path/url or piped input")
   fmt.Fprintln(os.Stderr, "Use the -h flag for more info")
   fmt.Fprintln(os.Stderr, "")
   os.Exit(0)
  }
  // Try to decode to check if it's image; if not, maybe error
  // We'll treat stdin as image if it decodes, otherwise error
  // For now, store data
  stdinData = data
  stdinIsImage = true
  inputs = []string{"stdin"}
 } else {
  inputs = args
 }

 // Parse save-bg and font-color for later
 var saveBgVals [4]int
 if saveBgStr != "" {
  parts := strings.Split(saveBgStr, ",")
  for i, p := range parts {
   v,_:= strconv.Atoi(strings.TrimSpace(p))
   saveBgVals[i]=v
  }
 } else {
  saveBgVals = [4]int{0,0,0,100}
 }
 var fontColorVals [3]int
 if fontColorStr != "" {
  parts := strings.Split(fontColorStr, ",")
  for i, p := range parts {
   v,_:= strconv.Atoi(strings.TrimSpace(p))
   fontColorVals[i]=v
  }
 } else {
  fontColorVals = [3]int{255,255,255}
 }

 // For each input, process
 for idx, input := range inputs {
  var imgData []byte
  var imgName string
  var img image.Image
  var err error
  var isURL bool
  var srcW, srcH int

  if stdinIsImage && input=="stdin" {
   imgData = stdinData
   imgName = "stdin"
   img, err = decodeImageData(imgData, imgName)
   if err != nil {
    fmt.Fprintf(os.Stderr, "Error: can't decode %s: %v\n", imgName, err)
    fmt.Fprintln(os.Stderr, "")
    continue
   }
  } else {
   imgName = input
   // Check if URL
   if strings.HasPrefix(input, "http://") || strings.HasPrefix(input, "https://") {
    isURL = true
    // Fetch
    resp, err := http.Get(input)
    if err != nil {
     fmt.Fprintf(os.Stderr, "Error: can't fetch content: Get \"%s\": %v\n", input, err)
     fmt.Fprintln(os.Stderr, "")
     continue
    }
    defer resp.Body.Close()
    data, err := io.ReadAll(resp.Body)
    if err != nil {
     fmt.Fprintf(os.Stderr, "Error: can't fetch content: Get \"%s\": %v\n", input, err)
     fmt.Fprintln(os.Stderr, "")
     continue
    }
    imgData = data
    // Derive name from URL last segment
    base := filepath.Base(input)
    if base == "" || base == "." || base == "/" {
     base = "url"
    }
    imgName = base
    img, err = decodeImageData(imgData, imgName)
    if err != nil {
     fmt.Fprintf(os.Stderr, "Error: can't decode %s: %v\n", input, err)
     fmt.Fprintln(os.Stderr, "")
     continue
    }
   } else {
    // File path
    data, err := os.ReadFile(input)
    if err != nil {
     fmt.Fprintf(os.Stderr, "Error: unable to open file: open %s: %v\n", input, err)
     fmt.Fprintln(os.Stderr, "")
     continue
    }
    imgData = data
    base := filepath.Base(input)
    ext := filepath.Ext(base)
    name := strings.TrimSuffix(base, ext)
    if name == "" {
     name = base
    }
    imgName = name
    // For saving, we need original base name without ext
    img, err = decodeImageData(imgData, input)
    if err != nil {
     fmt.Fprintf(os.Stderr, "Error: can't decode %s: %v\n", input, err)
     fmt.Fprintln(os.Stderr, "")
     continue
    }
   }
  }
  _ = isURL
  _ = imgData
  bounds := img.Bounds()
  srcW = bounds.Dx()
  srcH = bounds.Dy()
  if srcW==0 || srcH==0 {
   fmt.Fprintf(os.Stderr, "Error: can't decode %s: image: unknown format\n", input)
   fmt.Fprintln(os.Stderr, "")
   continue
  }

  // Determine target dimensions
  var targetW, targetH int
  if fullFlag {
   // Get terminal width
   termW, _, _ := getTerminalSize()
   if termW <=0 {
    termW = 80
   }
   targetW = termW
   targetH = srcH * targetW / srcW / 2
   if targetH <=0 { targetH =1}
  } else if dimensionsStr != "" {
   parts := strings.Split(dimensionsStr, ",")
   w,_:= strconv.Atoi(strings.TrimSpace(parts[0]))
   h,_:= strconv.Atoi(strings.TrimSpace(parts[1]))
   targetW = w
   targetH = h
  } else if widthFlag !=0 {
   targetW = widthFlag
   targetH = srcH * widthFlag / srcW / 2
   if targetH <=0 {targetH=1}
  } else if heightFlag !=0 {
   targetH = heightFlag
   targetW = srcW * heightFlag / srcH * 2
   if targetW <=0 {targetW=1}
  } else {
   // Default: try terminal height
   _, termH, _ := getTerminalSize()
   if termH <=0 {
    // Fallback to 24? But original would panic; we fallback to 20
    termH = 24
   }
   targetH = termH
   targetW = srcW * termH / srcH * 2
   if targetW <=0 {targetW=1}
  }

  // Handle braille vs ascii
  var asciiArt []string // each string is a line
  var brailleArt []string

  if brailleFlag {
   // For braille, targetW, targetH are in braille chars, need pixel size 2*W,4*H
   pixelW := targetW *2
   pixelH := targetH *4
   // Resize image to pixelW x pixelH
   resized := resizeImage(img, pixelW, pixelH)
   // Get grayscale matrix
   gray := make([][]int, pixelH)
   for y:=0; y<pixelH; y++ {
    gray[y]=make([]int, pixelW)
    for x:=0; x<pixelW; x++ {
     r,g,b,_ := resized.At(x, y).RGBA()
     r8:= uint8(r>>8)
     g8:= uint8(g>>8)
     b8:= uint8(b>>8)
     lum := (299*int(r8)+587*int(g8)+114*int(b8))/1000
     if negativeFlag {
      lum = 255 - lum
     }
     gray[y][x]=lum
    }
   }
   if ditherFlag {
    // Floyd-Steinberg
    for y:=0; y<pixelH; y++ {
     for x:=0; x<pixelW; x++ {
      old := gray[y][x]
      var newVal int
      if old >=128 {
       newVal =255
      } else {
       newVal =0
      }
      gray[y][x]=newVal
      err := old - newVal
      if x+1 < pixelW {
       gray[y][x+1] = clamp(gray[y][x+1]+err*7/16)
      }
      if y+1 < pixelH {
       if x-1 >=0 {
        gray[y+1][x-1] = clamp(gray[y+1][x-1]+err*3/16)
       }
       gray[y+1][x] = clamp(gray[y+1][x]+err*5/16)
       if x+1 < pixelW {
        gray[y+1][x+1] = clamp(gray[y+1][x+1]+err*1/16)
       }
      }
     }
    }
    // After dithering, threshold is 128 (already applied)
    brailleArt = convertBraille(gray, targetW, targetH, 128, true)
   } else {
    brailleArt = convertBraille(gray, targetW, targetH, thresholdFlag, false)
   }
   // Apply flip
   if flipXFlag || flipYFlag {
    brailleArt = flipBraille(brailleArt, flipXFlag, flipYFlag)
   }
  } else {
   // Ascii
   resized := resizeImage(img, targetW, targetH)
   // Determine char map
   var chars string
   if mapFlag != "" {
    chars = mapFlag
   } else if complexFlag {
    chars = complexMap
   } else {
    chars = defaultMap
   }
   // Convert
   asciiArt = convertAscii(resized, targetW, targetH, chars, negativeFlag)
   if flipXFlag || flipYFlag {
    asciiArt = flipAscii(asciiArt, flipXFlag, flipYFlag)
