func decodeBMP(r io.Reader) (image.Image, error) {
 // Read all
 data, err := io.ReadAll(r)
 if err != nil {
  return nil, err
 }
 if len(data) <54 {
  return nil, fmt.Errorf("bmp too small")
 }
 if data[0]!='B' || data[1]!='M' {
  return nil, fmt.Errorf("not bmp")
 }
 fileSize := int(data[2]) | int(data[3])<<8 | int(data[4])<<16 | int(data[5])<<24
 _ = fileSize
 offset := int(data[10]) | int(data[11])<<8 | int(data[12])<<16 | int(data[13])<<24
 headerSize := int(data[14]) | int(data[15])<<8 | int(data[16])<<16 | int(data[17])<<24
 if headerSize !=40 {
  return nil, fmt.Errorf("unsupported bmp header")
 }
 w := int(data[18]) | int(data[19])<<8 | int(data[20])<<16 | int(data[21])<<24
 h := int(data[22]) | int(data[23])<<8 | int(data[24])<<16 | int(data[25])<<24
 planes := int(data[26]) | int(data[27])<<8
 bpp := int(data[28]) | int(data[29])<<8
 comp := int(data[30]) | int(data[31])<<8 | int(data[32])<<16 | int(data[33])<<24
 _ = planes
 _ = comp
 topDown := false
 if h <0 {
  topDown = true
  h = -h
 }
 if w <=0 || h <=0 {
  return nil, fmt.Errorf("invalid bmp dimensions")
 }
 if bpp !=24 && bpp !=32 {
  return nil, fmt.Errorf("unsupported bpp %d", bpp)
 }
 // Row size padded to 4 bytes
 var rowSize int
 if bpp ==24 {
  rowSize = ((w*3 +3)/4)*4
 } else {
  rowSize = w*4
 }
 img := image.NewRGBA(image.Rect(0,0,w,h))
 // Pixel data
 for y:=0; y<h; y++ {
  var srcY int
  if topDown {
   srcY = y
  } else {
   srcY = h-1 - y
  }
  rowOffset := offset + srcY*rowSize
  if rowOffset+rowSize > len(data) {
   return nil, fmt.Errorf("bmp data truncated")
  }
  for x:=0; x<w; x++ {
   var r,g,b,a uint8
   a = 255
   if bpp==24 {
    b = data[rowOffset + x*3]
    g = data[rowOffset + x*3+1]
    r = data[rowOffset + x*3+2]
   } else {
    b = data[rowOffset + x*4]
    g = data[rowOffset + x*4+1]
    r = data[rowOffset + x*4+2]
    a = data[rowOffset + x*4+3]
   }
   img.Set(x, y, color.RGBA{r,g,b,a})
  }
 }
 return img, nil
}

func resizeImage(src image.Image, dstW, dstH int) image.Image {
 if dstW <=0 || dstH <=0 {
  return image.NewRGBA(image.Rect(0,0,dstW,dstH))
 }
 srcBounds := src.Bounds()
 srcW := srcBounds.Dx()
 srcH := srcBounds.Dy()
 if srcW==dstW && srcH==dstH {
  return src
 }
 dst := image.NewRGBA(image.Rect(0,0,dstW,dstH))
 // Use bilinear
 for y:=0; y<dstH; y++ {
  for x:=0; x<dstW; x++ {
   gx := (float64(x)+0.5)*float64(srcW)/float64(dstW) -0.5
   gy := (float64(y)+0.5)*float64(srcH)/float64(dstH) -0.5
   x1 := int(math.Floor(gx))
   y1 := int(math.Floor(gy))
   x2 := x1+1
   y2 := y1+1
   // Clamp
   if x1 <0 { x1=0; x2=0; gx=0 }
   if y1 <0 { y1=0; y2=0; gy=0 }
   if x2 >= srcW { x2 = srcW-1}
   if y2 >= srcH { y2 = srcH-1}
   if x1 >= srcW { x1 = srcW-1}
   if y1 >= srcH { y1 = srcH-1}
   dx := gx - float64(x1)
   dy := gy - float64(y1)
   if dx <0 { dx=0}
   if dx>1 {dx=1}
   if dy<0 {dy=0}
   if dy>1 {dy=1}
   c11 := src.At(srcBounds.Min.X+x1, srcBounds.Min.Y+y1)
   c21 := src.At(srcBounds.Min.X+x2, srcBounds.Min.Y+y1)
   c12 := src.At(srcBounds.Min.X+x1, srcBounds.Min.Y+y2)
   c22 := src.At(srcBounds.Min.X+x2, srcBounds.Min.Y+y2)
   r11,g11,b11,a11 := c11.RGBA()
   r21,g21,b21,a21 := c21.RGBA()
   r12,g12,b12,a12 := c12.RGBA()
   r22,g22,b22,a22 := c22.RGBA()
   // Convert to 0-255
   r11f := float64(r11>>8)
   g11f := float64(g11>>8)
   b11f := float64(b11>>8)
   a11f := float64(a11>>8)
   r21f := float64(r21>>8)
   g21f := float64(g21>>8)
   b21f := float64(b21>>8)
   a21f := float64(a21>>8)
   r12f := float64(r12>>8)
   g12f := float64(g12>>8)
   b12f := float64(b12>>8)
   a12f := float64(a12>>8)
   r22f := float64(r22>>8)
   g22f := float64(g22>>8)
   b22f := float64(b22>>8)
   a22f := float64(a22>>8)
   r := r11f*(1-dx)*(1-dy) + r21f*dx*(1-dy) + r12f*(1-dx)*dy + r22f*dx*dy
   g := g11f*(1-dx)*(1-dy) + g21f*dx*(1-dy) + g12f*(1-dx)*dy + g22f*dx*dy
   b := b11f*(1-dx)*(1-dy) + b21f*dx*(1-dy) + b12f*(1-dx)*dy + b22f*dx*dy
   a := a11f*(1-dx)*(1-dy) + a21f*dx*(1-dy) + a12f*(1-dx)*dy + a22f*dx*dy
   dst.Set(x,y, color.RGBA{uint8(r), uint8(g), uint8(b), uint8(a)})
  }
 }
 return dst
}

func convertAscii(img image.Image, w, h int, chars string, negative bool) []string {
 runes := []rune(chars)
 n := len(runes)
 lines := make([]string, h)
 for y:=0; y<h; y++ {
  var sb strings.Builder
  for x:=0; x<w; x++ {
   r,g,b,_ := img.At(x,y).RGBA()
   r8:= uint8(r>>8)
   g8:= uint8(g>>8)
   b8:= uint8(b>>8)
   lum := (299*int(r8)+587*int(g8)+114*int(b8))/1000
   idx := lum * n / 255
   if idx >= n { idx = n-1}
   if negative {
    idx = n-1 - idx
   }
   sb.WriteRune(runes[idx])
  }
  lines[y]=sb.String()
 }
 return lines
}

func convertBraille(gray [][]int, targetW, targetH int, threshold int, isDither bool) []string {
 lines := make([]string, targetH)
 for by:=0; by<targetH; by++ {
  var sb strings.Builder
  for bx:=0; bx<targetW; bx++ {
   bits := 0
   // Dot positions
   // (0,0)->1, (1,0)->8
   // (0,1)->2, (1,1)->16
   // (0,2)->4, (1,2)->32
   // (0,3)->64,(1,3)->128
   for dy:=0; dy<4; dy++ {
    for dx:=0; dx<2; dx++ {
     px := bx*2+dx
     py := by*4+dy
     lum := gray[py][px]
     var on bool
     if isDither {
      // Already dithered to 0 or 255
      on = lum >=128
     } else {
      on = lum >= threshold
     }
     if on {
      var bit int
      if dx==0 {
       if dy==0 { bit=0x01}
       if dy==1 { bit=0x02}
       if dy==2 { bit=0x04}
       if dy==3 { bit=0x40}
      } else {
       if dy==0 { bit=0x08}
       if dy==1 { bit=0x10}
       if dy==2 { bit=0x20}
       if dy==3 { bit=0x80}
      }
      bits |= bit
     }
    }
   }
   r := rune(0x2800 + bits)
   sb.WriteRune(r)
  }
  lines[by]=sb.String()
 }
 return lines
}

