new="func resizeNearest(src image.Image, dstW, dstH int) image.Image {
 if dstW <=0 || dstH <=0 {
  return image.NewRGBA(image.Rect(0,0,dstW,dstH))
 }
 srcBounds := src.Bounds()
 srcW := srcBounds.Dx()
 srcH := srcBounds.Dy()
 if srcW==dstW && srcH==dstH {
  return src
 }
 dst := image.NewRGBA(image.Rect(0,0,dstW,dstH))
 for y:=0; y<dstH; y++ {
  for x:=0; x<dstW; x++ {
   sx := x*srcW/dstW
   sy := y*srcH/dstH
   dst.Set(x,y, src.At(srcBounds.Min.X+sx, srcBounds.Min.Y+sy))
  }
 }
 return dst
}

func resizeImage(src image.Image, dstW, dstH int) image.Image {"
